<?php
namespace FeedWriter; use \DateTime; use \DateTimeInterface; /**
 * Universal Feed Writer
 *
 * Item class - Used as feed element in Feed class
 *
 * @package         UniversalFeedWriter
 * @author          Anis uddin Ahmad <anisniit@gmail.com>
 * @link            http://www.ajaxray.com/projects/rss
 */
class Item { private $elements = array(); private $version; private $_cpt = 0; public function __construct($version = Feed::RSS2) { $this->version = $version; } private function cpt() { return $this->_cpt++; } public function addElement($elementName, $content, ?array $attributes = null, $overwrite = FALSE, $allowMultiple = FALSE) { if (empty($elementName)) throw new \InvalidArgumentException('The element name may not be empty or NULL.'); if (!is_string($elementName)) throw new \InvalidArgumentException('The element name must be a string.'); $key = $elementName; if (isset($this->elements[$elementName]) && !$overwrite) { if (!$allowMultiple) return $this; $key .= '-' . $this->cpt(); } $this->elements[$key]['name'] = $elementName; $this->elements[$key]['content'] = $content; $this->elements[$key]['attributes'] = $attributes; return $this; } public function addElementArray(array $elementArray) { foreach ($elementArray as $elementName => $content) { $this->addElement($elementName, $content); } return $this; } public function getElements() { if ($this->version == Feed::ATOM) { if (!array_key_exists('id', $this->elements)) $this->setId(Feed::uuid($this->elements['title']['content'], 'urn:uuid:')); if (!array_key_exists('content', $this->elements) && !array_key_exists('link', $this->elements)) throw new InvalidOperationException('ATOM feed entries need a link or a content element. Call the setLink or setContent method.'); } else if ($this->version == Feed::RSS1) { if (!array_key_exists('title', $this->elements)) throw new InvalidOperationException('RSS1 feed entries need a title element. Call the setTitle method.'); if (!array_key_exists('link', $this->elements)) throw new InvalidOperationException('RSS1 feed entries need a link element. Call the setLink method.'); } return $this->elements; } public function getVersion() { return $this->version; } public function setDescription($description) { $tag = ($this->version == Feed::ATOM) ? 'summary' : 'description'; return $this->addElement($tag, $description); } public function setContent($content) { if ($this->version != Feed::ATOM) throw new InvalidOperationException('The content element is supported in ATOM feeds only.'); return $this->addElement('content', $content, array('type' => 'html')); } public function setTitle($title) { return $this->addElement('title', $title); } public function setDate($date) { if (!is_numeric($date)) { if ($date instanceof DateTimeInterface || $date instanceof DateTime) $date = $date->getTimestamp(); else { $date = strtotime($date); if ($date === FALSE) throw new \InvalidArgumentException('The given date string was not parseable.'); } } elseif ($date < 0) throw new \InvalidArgumentException('The given date is not an UNIX timestamp.'); if ($this->version == Feed::ATOM) { $tag = 'updated'; $value = date(\DATE_ATOM, $date); } elseif ($this->version == Feed::RSS2) { $tag = 'pubDate'; $value = date(\DATE_RSS, $date); } else { $tag = 'dc:date'; $value = date("Y-m-d", $date); } return $this->addElement($tag, $value); } public function setLink($link) { if ($this->version == Feed::RSS2 || $this->version == Feed::RSS1) { $this->addElement('link', $link); } else { $this->addElement('link','',array('href'=>$link)); $this->setId(Feed::uuid($link,'urn:uuid:')); } return $this; } public function addEnclosure($url, $length, $type, $multiple = TRUE) { if ($this->version == Feed::RSS1) throw new InvalidOperationException('Media attachment is not supported in RSS1 feeds.'); if (!is_numeric($length) || $length < 0) throw new \InvalidArgumentException('The length parameter must be an integer and greater or equals to zero.'); if (!is_string($type) || preg_match('/.+\/.+/', $type) != 1) throw new \InvalidArgumentException('type parameter must be a string and a MIME type.'); $attributes = array('length' => $length, 'type' => $type); if ($this->version == Feed::RSS2) { $attributes['url'] = $url; $this->addElement('enclosure', '', $attributes, FALSE, $multiple); } else { $attributes['href'] = $url; $attributes['rel'] = 'enclosure'; $this->addElement('atom:link', '', $attributes, FALSE, $multiple); } return $this; } public function setAuthor($author, $email = null, $uri = null) { if ($this->version == Feed::RSS1) throw new InvalidOperationException('The author element is not supported in RSS1 feeds.'); if ($email != null && preg_match('/.+@.+/', $email) != 1) throw new \InvalidArgumentException('The email address is syntactically incorrect.'); if ($this->version == Feed::RSS2) { if ($email != null) $author = $email . ' (' . $author . ')'; $this->addElement('author', $author); } else { $elements = array('name' => $author); if ($email != null) $elements['email'] = $email; if ($uri != null) $elements['uri'] = $uri; $this->addElement('author', $elements); } return $this; } public function setId($id, $permaLink = false) { if ($this->version == Feed::RSS2) { if (!is_bool($permaLink)) throw new \InvalidArgumentException('The permaLink parameter must be boolean.'); $permaLink = $permaLink ? 'true' : 'false'; $this->addElement('guid', $id, array('isPermaLink' => $permaLink)); } elseif ($this->version == Feed::ATOM) { $validSchemes = array('aaa', 'aaas', 'about', 'acap', 'acct', 'bb', 'cap', 'cid', 'coap', 'coap+tcp', 'coap+ws', 'coaps', 'coaps+tcp', 'coaps+ws', 'crid', 'data', 'dav', 'dict', 'dns', 'drop', 'dtn', 'example', 'fax', 'file', 'filesystem', 'ftp', 'geo', 'go', 'gopher', 'grd', 'h323', 'http', 'https', 'iax', 'icap', 'im', 'imap', 'info', 'ipn', 'ipp', 'ipps', 'iris', 'iris.beep', 'iris.lwz', 'iris.xpc', 'iris.xpcs', 'jabber', 'ldap', 'leaptofrogans', 'mailserver', 'mailto', 'mid', 'modem', 'msrp', 'msrps', 'mt', 'mtqp', 'mupdate', 'news', 'nfs', 'ni', 'nih', 'nntp', 'opaquelocktoken', 'p1', 'pack', 'pkcs11', 'pop', 'pres', 'prospero', 'reload', 'rtsp', 'rtsps', 'rtspu', 'service', 'session', 'shttp (OBSOLETE)', 'sieve', 'sip', 'sips', 'sms', 'snews', 'snmp', 'soap.beep', 'soap.beeps', 'stun', 'stuns', 'tag', 'tel', 'telnet', 'tftp', 'thismessage', 'tip', 'tn3270', 'turn', 'turns', 'tv', 'upt', 'urn', 'vemmi', 'videotex', 'vnc', 'wais', 'wpid', 'ws', 'wss', 'xcon', 'xcon-userid', 'xmlrpc.beep', 'xmlrpc.beeps', 'xmpp', 'z39.50', 'z39.50r', 'z39.50s'); $found = FALSE; $checkId = strtolower($id); foreach($validSchemes as $scheme) if (strrpos($checkId, $scheme . ':', -strlen($checkId)) !== FALSE) { $found = TRUE; break; } if (!$found) throw new \InvalidArgumentException("The ID must begin with an IANA-registered URI scheme."); $this->addElement('id', $id, NULL, TRUE); } else throw new InvalidOperationException('A unique ID is not supported in RSS1 feeds.'); return $this; } }
